<script setup lang="ts">import{ref}from'vue';import{useI18n}from'vue-i18n';import{quickPrompts,skills,tasks,statusLabel}from'@/data/mock';const value=ref('');const{t}=useI18n()</script><template><section class="flex-1 overflow-y-auto"><div class="mx-auto flex min-h-full max-w-3xl flex-col justify-center px-6 py-12"><div class="text-center"><span class="mx-auto flex size-12 items-center justify-center rounded-2xl bg-inverted text-inverted"><UIcon name="i-lucide-sparkles" class="size-6"/></span><h1 class="mt-5 text-3xl font-semibold">{{t('home.hello')}}</h1><p class="mt-2 text-sm text-muted">{{t('home.sub')}}</p></div><UCard class="mt-8"><UTextarea v-model="value" autoresize :rows="3" :placeholder="t('home.placeholder')" class="w-full" variant="none"/><div class="mt-2 flex justify-between"><div class="flex gap-1"><UButton icon="i-lucide-paperclip" color="neutral" variant="ghost"/><UButton icon="i-lucide-at-sign" color="neutral" variant="ghost"/><UButton icon="i-lucide-puzzle" label="技能" color="neutral" variant="ghost"/></div><UButton icon="i-lucide-arrow-up" :disabled="!value.trim()"/></div></UCard><div class="mt-4 flex flex-wrap justify-center gap-2"><UButton v-for="q in quickPrompts" :key="q.label" :label="`${q.emoji} ${q.label}`" color="neutral" variant="outline" size="xs" @click="value=q.label"/></div><div class="mt-12 grid gap-6 md:grid-cols-2"><section><h2 class="mb-3 text-sm font-medium">{{t('home.recent')}}</h2><div class="flex flex-col gap-2"><RouterLink v-for="task in tasks" :key="task.id" :to="`/task/${task.id}`"><UCard class="hover:bg-elevated"><div class="flex justify-between gap-2"><b class="truncate text-sm">{{task.title}}</b><UBadge size="xs" color="neutral">{{statusLabel[task.status]}}</UBadge></div><p class="mt-1 text-xs text-muted">{{task.project}} · {{task.updatedAt}}</p></UCard></RouterLink></div></section><section><h2 class="mb-3 text-sm font-medium">{{t('home.used')}}</h2><div class="flex flex-col gap-2"><UCard v-for="skill in skills.filter(s=>s.installed)" :key="skill.id"><div class="flex gap-3"><span class="text-xl">{{skill.emoji}}</span><div><b class="text-sm">{{skill.name}}</b><p class="text-xs text-muted">{{skill.desc}}</p></div></div></UCard></div></section></div></div></section></template>
